  void nullDatumReturnsNullWithoutNeedingSchemaOrModel() {
    Object result = AvroJson.convertToAvro(null, null, null);

    assertNull(result);
  }

  @Test
  void convertsPrimitiveValuesAccordingToSchema() {
    assertEquals(
        Boolean.TRUE,
        AvroJson.convertToAvro(MODEL, AvroJson.parse("true"), Schema.create(Schema.Type.BOOLEAN)));
    assertEquals(
        12,
        AvroJson.convertToAvro(MODEL, AvroJson.parse("12"), Schema.create(Schema.Type.INT)));
    assertEquals(
        12L,
        AvroJson.convertToAvro(MODEL, AvroJson.parse("12"), Schema.create(Schema.Type.LONG)));
    assertEquals(
        12.5d,
        AvroJson.convertToAvro(MODEL, AvroJson.parse("12.5"), Schema.create(Schema.Type.DOUBLE)));
    assertEquals(
        "parquet",
        AvroJson.convertToAvro(
            MODEL, AvroJson.parse("\"parquet\""), Schema.create(Schema.Type.STRING)));
  }

  @Test
  void rejectsJsonKindsIncompatibleWithPrimitiveSchemas() {
    assertThrows(
        RecordException.class,
        () ->
            AvroJson.convertToAvro(
                MODEL, AvroJson.parse("\"not-an-int\""), Schema.create(Schema.Type.INT)));
    assertThrows(
        RecordException.class,
        () ->
            AvroJson.convertToAvro(
                MODEL, AvroJson.parse("1"), Schema.create(Schema.Type.BOOLEAN)));
    assertThrows(
        RecordException.class,
        () ->
            AvroJson.convertToAvro(
                MODEL, AvroJson.parse("1.5"), Schema.create(Schema.Type.INT)));
  }

  @Test
  void convertsNestedRecordArrayAndMapValues() {
    Schema recordSchema =
        schema(
            "{"
                + "\"type\":\"record\","
                + "\"name\":\"Container\","
                + "\"fields\":["
                + "{\"name\":\"name\",\"type\":\"string\"},"
                + "{\"name\":\"numbers\","
                + "\"type\":{\"type\":\"array\",\"items\":\"int\"}},"
                + "{\"name\":\"attributes\","
                + "\"type\":{\"type\":\"map\",\"values\":\"long\"}}"
                + "]"
                + "}");

    GenericRecord result =
        (GenericRecord)
            AvroJson.convertToAvro(
                MODEL,
                AvroJson.parse(
                    "{\"name\":\"example\",\"numbers\":[1,2,3],"
                        + "\"attributes\":{\"first\":10,\"second\":20}}"),
                recordSchema);

    assertEquals("example", result.get("name"));
    assertEquals(List.of(1, 2, 3), result.get("numbers"));
    assertEquals(Map.of("first", 10L, "second", 20L), result.get("attributes"));
  }

  @Test
  void preservesMapEntriesAndConvertsEmptyContainers() {
    Schema mapSchema = Schema.createMap(Schema.create(Schema.Type.STRING));
    Schema arraySchema = Schema.createArray(Schema.create(Schema.Type.INT));

    Object map =
        AvroJson.convertToAvro(MODEL, AvroJson.parse("{\"b\":\"two\",\"a\":\"one\"}"), mapSchema);
    Object array = AvroJson.convertToAvro(MODEL, AvroJson.parse("[]"), arraySchema);

    assertEquals(Map.of("b", "two", "a", "one"), map);
    assertEquals(List.of(), array);
  }

  @Test
  void resolvesNumericAndNullUnions() {
    Schema numericUnion =
        Schema.createUnion(
            List.of(Schema.create(Schema.Type.INT), Schema.create(Schema.Type.LONG)));

    Object numericResult =
        AvroJson.convertToAvro(MODEL, AvroJson.parse("7"), numericUnion);

    Schema nullableString =
        Schema.createUnion(
            List.of(Schema.create(Schema.Type.NULL), Schema.create(Schema.Type.STRING)));
    Object nullResult =
        AvroJson.convertToAvro(MODEL, AvroJson.parse("null"), nullableString);

    assertEquals(Integer.class, numericResult.getClass());
    assertEquals(7, numericResult);
    assertNull(nullResult);
  }

  @Test
  void convertsEnumUsingTheSuppliedGenericDataModel() {
    Schema enumSchema =
        schema(
            "{\"type\":\"enum\",\"name\":\"Color\","
                + "\"symbols\":[\"RED\",\"GREEN\",\"BLUE\"]}");

    Object result =
        AvroJson.convertToAvro(MODEL, AvroJson.parse("\"GREEN\""), enumSchema);

    assertEquals("GREEN", result.toString());
    assertEquals(enumSchema, ((GenericData.EnumSymbol) result).getSchema());
  }

  @Test
  void convertsBinaryJsonNodesToByteBuffers() {
    Schema bytesSchema = Schema.create(Schema.Type.BYTES);
    JsonNode binaryNode = BinaryNode.valueOf(new byte[] {1, 2, 3});

    Object result = AvroJson.convertToAvro(MODEL, binaryNode, bytesSchema);

    assertTrue(result instanceof ByteBuffer);
    ByteBuffer buffer = (ByteBuffer) result;
    assertArrayEquals(new byte[] {1, 2, 3}, buffer.array());
    assertEquals(3, buffer.remaining());
  }

  @Test
  void convertsFixedValuesAndRejectsValuesOfIncorrectSize() {
    Schema fixedSchema = Schema.createFixed("Identifier", null, null, 3);
    JsonNode exactBinary = BinaryNode.valueOf(new byte[] {4, 5, 6});

    Object result = AvroJson.convertToAvro(MODEL, exactBinary, fixedSchema);

    assertTrue(result instanceof GenericFixed);
    assertArrayEquals(new byte[] {4, 5, 6}, ((GenericFixed) result).bytes());

    assertThrows(
        RecordException.class,
        () ->
            AvroJson.convertToAvro(
                MODEL, BinaryNode.valueOf(new byte[] {1, 2}), fixedSchema));
    assertThrows(
        RecordException.class,
        () ->
            AvroJson.convertToAvro(
                MODEL, BinaryNode.valueOf(new byte[] {1, 2, 3, 4}), fixedSchema));
  }

  @Test
  void nullSchemaTypeAlwaysProducesNull() {
    Object result =
        AvroJson.convertToAvro(
            MODEL, AvroJson.parse("\"ignored\""), Schema.create(Schema.Type.NULL));

    assertNull(result);
  }
}

