  @Test
  void convertsNestedRecordArrayAndMap() {
    Schema schema =
        new Schema.Parser()
            .parse(
                """
                {
                  "type": "record",
                  "name": "Root",
                  "fields": [
                    {"name": "id", "type": "int"},
                    {"name": "values", "type": {"type": "array", "items": "string"}},
                    {"name": "counts", "type": {"type": "map", "values": "long"}}
                  ]
                }
                """);

    JsonNode datum =
        AvroJson.parse(
            """
            {
              "id": 7,
              "values": ["a", "b"],
              "counts": {"first": 11, "second": 13}
            }
            """);

    GenericRecord result =
        assertInstanceOf(
            GenericRecord.class, AvroJson.convertToAvro(MODEL, datum, schema));

    assertEquals(7, result.get("id"));
    assertEquals(List.of("a", "b"), result.get("values"));
    assertEquals(Map.of("first", 11L, "second", 13L), result.get("counts"));
